import { EMPTY_OBJ, EMPTY_ARR, IS_NON_DIMENSIONAL } from '../constants';
import { BaseComponent } from '../component';
import { createVNode, findMatchingIndex, Fragment } from './children';
import { isArray, slice } from '../util';
import options from '../options';

/** The `.render()` method for a PFC backing instance. */
function doRender(props, state, context) {
	return this.constructor(props, context);
}

function eventProxy(e) {
	const eventHandler = this._listeners[e.type + false];
	if (!e._dispatched) {
		e._dispatched = Date.now();
	} else if (e._dispatched <= eventHandler._attached) {
		return;
	}
	return eventHandler(options.event ? options.event(e) : e);
}

function eventProxyCapture(e) {
	return this._listeners[e.type + true](options.event ? options.event(e) : e);
}

class TreeCoordinator {
	constructor() {
		this._runtime = {
			options,
			emptyObj: EMPTY_OBJ,
			emptyArr: EMPTY_ARR,
			fragmentType: Fragment,
			baseComponent: BaseComponent,
			createVNode,
			rerenderQueue: [],
			rerenderCount: 0,
			prevDebounce: undefined,
			defer:
				typeof Promise == 'function'
					? Promise.prototype.then.bind(Promise.resolve())
					: setTimeout,
			slice,
			isArray,
			nonDimensional: IS_NON_DIMENSIONAL
		};
		this._runtime.flush = this.flushRenderQueue.bind(this);
	}

	assign(obj, props) {
		for (let i in props) obj[i] = props[i];
		return obj;
	}

	removeNode(node) {
		let parentNode = node.parentNode;
		if (parentNode) parentNode.removeChild(node);
	}

	isClassComponent(type) {
		return 'prototype' in type && type.prototype.render;
	}

	isInvalidChild(child) {
		return child == null || typeof child == 'boolean' || typeof child == 'function';
	}

	isTextChild(child) {
		return (
			child.constructor == String ||
			typeof child == 'number' ||
			typeof child == 'bigint'
		);
	}

	extractRenderResult(tmp) {
		let isTopLevelFragment =
			tmp != null && tmp.type === Fragment && tmp.key == null;
		return isTopLevelFragment ? tmp.props.children : tmp;
	}

	sortByDepth(a, b) {
		return a._vnode._depth - b._vnode._depth;
	}

	syncTextContent(dom, oldProps, newProps, isHydrating) {
		if (oldProps !== newProps && (!isHydrating || dom.data !== newProps)) {
			dom.data = newProps;
		}
	}

	collectExistingAttributes(dom) {
		let oldProps = {};
		for (let i = 0; i < dom.attributes.length; i++) {
			oldProps[dom.attributes[i].name] = dom.attributes[i].value;
		}
		return oldProps;
	}

	applyDangerousHTML(dom, oldHtml, newHtml) {
		if (
			!newHtml ||
			((!oldHtml || newHtml.__html != oldHtml.__html) &&
				newHtml.__html !== dom.innerHTML)
		) {
			dom.innerHTML = (newHtml && newHtml.__html) || '';
		}
	}

	createHostNode(nodeType, newProps, isSvg) {
		if (nodeType === null) {
			return document.createTextNode(newProps);
		}
		if (isSvg) {
			return document.createElementNS('http://www.w3.org/2000/svg', nodeType);
		}
		return document.createElement(nodeType, newProps.is && newProps);
	}

	placeChild(parentDom, newDom, oldDom) {
		if (newDom != oldDom) {
			parentDom.insertBefore(newDom, oldDom || null);
		}
		return newDom.nextSibling;
	}

	catchError(error, vnode, oldVNode, errorInfo) {
		let component, ctor, handled;

		for (; (vnode = vnode._parent); ) {
			if ((component = vnode._component) && !component._processingException) {
				try {
					ctor = component.constructor;

					if (ctor && ctor.getDerivedStateFromError != null) {
						component.setState(ctor.getDerivedStateFromError(error));
						handled = component._dirty;
					}

					if (component.componentDidCatch != null) {
						component.componentDidCatch(error, errorInfo || {});
						handled = component._dirty;
					}

					if (handled) {
						return (component._pendingError = component);
					}
				} catch (e) {
					error = e;
				}
			}
		}

		throw error;
	}

	getDomSibling(vnode, childIndex) {
		if (childIndex == null) {
			return vnode._parent
				? this.getDomSibling(vnode._parent, vnode._index + 1)
				: null;
		}

		let sibling;
		for (; childIndex < vnode._children.length; childIndex++) {
			sibling = vnode._children[childIndex];

			if (sibling != null && sibling._dom != null) {
				return sibling._dom;
			}
		}

		return typeof vnode.type == 'function' ? this.getDomSibling(vnode) : null;
	}

	updateParentDomPointers(vnode) {
		if ((vnode = vnode._parent) != null && vnode._component != null) {
			vnode._dom = vnode._component.base = null;
			for (let i = 0; i < vnode._children.length; i++) {
				let child = vnode._children[i];
				if (child != null && child._dom != null) {
					vnode._dom = vnode._component.base = child._dom;
					break;
				}
			}

			return this.updateParentDomPointers(vnode);
		}
	}

	forceComponentUpdate(component, callback) {
		if (component._vnode) {
			component._force = true;
			if (callback) component._renderCallbacks.push(callback);
			this.enqueueRender(component);
		}
	}

	applyStateUpdate(component, update, callback) {
		let s;
		if (component._nextState != null && component._nextState !== component.state) {
			s = component._nextState;
		} else {
			s = component._nextState = this.assign({}, component.state);
		}

		if (typeof update == 'function') {
			update = update(this.assign({}, s), component.props);
		}

		if (update) {
			this.assign(s, update);
		}

		if (update == null) return;

		if (component._vnode) {
			if (callback) {
				component._stateCallbacks.push(callback);
			}
			this.enqueueRender(component);
		}
	}

	diffProps(dom, newProps, oldProps, isSvg, hydrate) {
		let i;

		for (i in oldProps) {
			if (i !== 'children' && i !== 'key' && !(i in newProps)) {
				this.setProperty(dom, i, null, oldProps[i], isSvg);
			}
		}

		for (i in newProps) {
			if (
				(!hydrate || typeof newProps[i] == 'function') &&
				i !== 'children' &&
				i !== 'key' &&
				i !== 'value' &&
				i !== 'checked' &&
				oldProps[i] !== newProps[i]
			) {
				this.setProperty(dom, i, newProps[i], oldProps[i], isSvg);
			}
		}
	}

	reorderChildren(childVNode, oldDom, parentDom) {
		let c = childVNode._children;

		let tmp = 0;
		for (; c && tmp < c.length; tmp++) {
			let vnode = c[tmp];
			if (vnode) {
				vnode._parent = childVNode;

				if (typeof vnode.type == 'function') {
					oldDom = this.reorderChildren(vnode, oldDom, parentDom);
				} else {
					oldDom = this.placeChild(parentDom, vnode._dom, oldDom);
				}
			}
		}

		return oldDom;
	}

	resolveSkew(matchingIndex, skewedIndex, remainingOldChildren, newChildrenLength, isMounting, skew) {
		if (isMounting) {
			if (matchingIndex == -1) {
				skew--;
			}
		} else if (matchingIndex !== skewedIndex) {
			if (matchingIndex === skewedIndex + 1) {
				skew++;
			} else if (matchingIndex > skewedIndex) {
				if (remainingOldChildren > newChildrenLength - skewedIndex) {
					skew += matchingIndex - skewedIndex;
				} else {
					skew--;
				}
			} else if (matchingIndex < skewedIndex) {
