export const coordinator = new TreeCoordinator();

export function diff(
	parentDom,
	newVNode,
	oldVNode,
	globalContext,
	isSvg,
	excessDomChildren,
	commitQueue,
	oldDom,
	isHydrating,
	refQueue
) {
	return coordinator.diff(
		parentDom,
		newVNode,
		oldVNode,
		globalContext,
		isSvg,
		excessDomChildren,
		commitQueue,
		oldDom,
		isHydrating,
		refQueue
	);
}

export function commitRoot(commitQueue, root, refQueue) {
	return coordinator.commitRoot(commitQueue, root, refQueue);
}

export function applyRef(ref, value, vnode) {
	return coordinator.applyRef(ref, value, vnode);
}

export function unmount(vnode, parentVNode, skipRemove) {
	return coordinator.unmount(vnode, parentVNode, skipRemove);
}

